import*as THREE from'three';import{OrbitControls}from'three/addons/controls/OrbitControls.js';
export function openMotion(objects){const dialog=document.querySelector('#motionDialog'),mount=document.querySelector('#motionCanvas');const humerus=[...objects.values()].find(o=>/^Humerus\.l\./.test(o.userData.record.name));if(!humerus)throw Error('Erkek referansındaki kol kemikleri yüklenmeli.');
 dialog.showModal();mount.replaceChildren();const renderer=new THREE.WebGLRenderer({antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.setSize(mount.clientWidth,mount.clientHeight);renderer.toneMapping=THREE.ACESFilmicToneMapping;mount.appendChild(renderer.domElement);const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(40,mount.clientWidth/mount.clientHeight,.01,10);scene.add(new THREE.HemisphereLight(0xffeee0,0x344656,2));const light=new THREE.DirectionalLight(0xffffff,2);light.position.set(1,2,3);scene.add(light);
 const hbox=new THREE.Box3().setFromObject(humerus),hc=hbox.getCenter(new THREE.Vector3()),pivot=new THREE.Vector3(hc.x,hbox.min.y+.015,hc.z);const lower=new THREE.Group();lower.position.copy(pivot);scene.add(lower);const muscles=[];const resources=[];
 for(const o of objects.values()){const r=o.userData.record;if(!/\.l\./.test(r.name)||r.sex!=='male')continue;const box=new THREE.Box3().setFromObject(o),c=box.getCenter(new THREE.Vector3());const bone=r.layer==='skeleton'&&(o===humerus||(c.x>.09&&c.y<pivot.y+.05&&c.y>.52));const muscle=r.layer==='muscular'&&/biceps brachii/i.test(r.name);if(!bone&&!muscle)continue;const geometry=o.geometry.clone();geometry.applyMatrix4(o.matrixWorld);const material=new THREE.MeshStandardMaterial({color:muscle?'#a65049':'#ded1b7',roughness:.55});const copy=new THREE.Mesh(geometry,material);resources.push(copy);if(bone&&o!==humerus){geometry.translate(-pivot.x,-pivot.y,-pivot.z);lower.add(copy);}else{scene.add(copy);if(muscle)muscles.push({mesh:copy,base:geometry.attributes.position.array.slice()});}}
 const controls=new OrbitControls(camera,renderer.domElement);controls.target.set(hc.x,hc.y-.05,hc.z+.08);camera.position.set(hc.x+.8,hc.y+.1,hc.z+1.1);controls.update();let animation=0,playing=false,start=0;
 function draw(angle){const rad=angle*Math.PI/180;lower.rotation.x=-rad;const insertion=pivot.clone().add(new THREE.Vector3(0,-.07,0));const moved=insertion.clone().sub(pivot).applyAxisAngle(new THREE.Vector3(1,0,0),-rad).add(pivot);const delta=moved.sub(insertion);for(const {mesh,base}of muscles){const p=mesh.geometry.attributes.position;for(let i=0;i<p.count;i++){const y=base[i*3+1],weight=THREE.MathUtils.clamp((hbox.max.y-y)/(hbox.max.y-pivot.y+.07),0,1);p.setXYZ(i,base[i*3]+delta.x*weight,y+delta.y*weight,base[i*3+2]+delta.z*weight);}p.needsUpdate=true;mesh.geometry.computeVertexNormals();}document.querySelector('#motionAngleValue').textContent=Math.round(angle)+'°';renderer.render(scene,camera);}
 const slider=document.querySelector('#motionAngle'),play=document.querySelector('#motionPlay');slider.value=0;draw(0);controls.addEventListener('change',()=>draw(+slider.value));slider.oninput=()=>{playing=false;cancelAnimationFrame(animation);play.textContent='Oynat';draw(+slider.value);};function tick(time){if(!playing)return;if(!start)start=time;const angle=55-55*Math.cos((time-start)/1800);slider.value=angle;draw(angle);animation=requestAnimationFrame(tick);}play.onclick=()=>{playing=!playing;play.textContent=playing?'Duraklat':'Oynat';if(playing){start=0;animation=requestAnimationFrame(tick);}else cancelAnimationFrame(animation);};
 const observer=new ResizeObserver(()=>{camera.aspect=mount.clientWidth/mount.clientHeight;camera.updateProjectionMatrix();renderer.setSize(mount.clientWidth,mount.clientHeight);draw(+slider.value);});observer.observe(mount);
 dialog.addEventListener('close',()=>{playing=false;cancelAnimationFrame(animation);observer.disconnect();controls.dispose();for(const o of resources){o.geometry.dispose();o.material.dispose();}renderer.dispose();mount.replaceChildren();},{once:true});
}
